  function launchCarThinking(){
    var parts=[
      {id:'rings',name:'Piston Rings',desc:'Pick up the piston assembly, then seat the rings onto the piston.',art:'piston'},
      {id:'piston',name:'Piston into Block',desc:'Pick up the piston assembly and lower it into the engine block.',art:'block'},
      {id:'cam',name:'Upper Block & Camshaft',desc:'Install the upper hardware and seat the camshaft into the head.',art:'cam'},
      {id:'engine',name:'Engine into Car',desc:'Lift the completed engine and mount it into the chassis.',art:'engine'}
    ];
    var score={engine:0,uphill:0,downhill:0,total:0};
    var body='<div class="car-thinking-game">'+
      '<div class="car-stage-top"><div><span class="hub-tag">THINKERS</span><h4 id="ct-title">STAGE 1 · ENGINE ASSEMBLY</h4><p id="ct-sub" class="study-muted">Build the engine one component at a time. Every timing check is one chance only.</p></div><div class="ct-score"><span>TOTAL</span><b id="ct-total">0</b><small>/ 9,000</small></div></div>'+
      '<div class="ct-progress"><div id="ct-progress-fill"></div></div>'+
      '<div id="ct-stage"></div>'+
    '</div>';
    var o=ovOpen('🧠 Build, Climb & Race','Three stages · 9,000 points maximum · one attempt per timing check.',body);if(!o)return;
    var stageEl=document.getElementById('ct-stage'), titleEl=document.getElementById('ct-title'), subEl=document.getElementById('ct-sub'), totalEl=document.getElementById('ct-total'), progress=document.getElementById('ct-progress-fill');
    var timers=[],raf=null,closed=false;
    function cleanup(){timers.forEach(clearTimeout);timers=[];if(raf)cancelAnimationFrame(raf);raf=null;}
    function later(fn,ms){var id=setTimeout(function(){if(!closed)fn();},ms);timers.push(id);return id;}
    function setProgress(n){if(progress)progress.style.width=Math.max(0,Math.min(100,n))+'%';}
    function setScore(){score.total=score.engine+score.uphill+score.downhill;if(totalEl)totalEl.textContent=score.total.toLocaleString();}
    function finish(){
      cleanup();setProgress(100);titleEl.textContent='CHALLENGE COMPLETE';subEl.textContent='Your final engineering score is based on the three 3,000-point stages.';
      stageEl.innerHTML='<div class="ct-final"><div class="ct-final-score">'+score.total.toLocaleString()+' <span>/ 9,000</span></div><div class="ct-score-breakdown"><div><b>ENGINE</b><strong>'+score.engine.toLocaleString()+'</strong><small>/ 3,000</small></div><div><b>UPHILL</b><strong>'+score.uphill.toLocaleString()+'</strong><small>/ 3,000</small></div><div><b>DOWNHILL</b><strong>'+score.downhill.toLocaleString()+'</strong><small>/ 3,000</small></div></div><div class="car-feedback">RESULT · Every correct assembly and shift added to your score. A missed timing check stayed missed and could not be retried.</div></div>';
    }
    function svgFor(kind){
      if(kind==='piston') return '<svg viewBox="0 0 100 100" width="90" height="90"><ellipse cx="50" cy="23" rx="28" ry="11" fill="#c8d0d8"/><rect x="22" y="22" width="56" height="48" rx="10" fill="#9aa6b2"/><ellipse cx="50" cy="70" rx="28" ry="11" fill="#6f7b87"/><path d="M31 36h38M31 48h38" stroke="#eef4f7" stroke-width="4" opacity=".65"/><circle cx="50" cy="82" r="10" fill="#4a5562"/><circle cx="50" cy="82" r="5" fill="#10161d"/></svg>';
      if(kind==='block') return '<svg viewBox="0 0 150 100" width="140" height="90"><rect x="12" y="22" width="126" height="58" rx="8" fill="#56616d" stroke="#aab4bd" stroke-width="3"/><rect x="28" y="10" width="20" height="18" rx="3" fill="#788692"/><rect x="65" y="10" width="20" height="18" rx="3" fill="#788692"/><rect x="102" y="10" width="20" height="18" rx="3" fill="#788692"/><circle cx="38" cy="51" r="10" fill="#1b232c"/><circle cx="75" cy="51" r="10" fill="#1b232c"/><circle cx="112" cy="51" r="10" fill="#1b232c"/></svg>';
      if(kind==='cam') return '<svg viewBox="0 0 150 100" width="140" height="90"><rect x="12" y="35" width="126" height="40" rx="8" fill="#4f5b67"/><path d="M20 35h110v-12H20z" fill="#7e8a96"/><path d="M34 30c5-16 13-16 18 0s13 16 18 0 13-16 18 0 13 16 18 0" fill="none" stroke="#dce4ea" stroke-width="7" stroke-linecap="round"/></svg>';
      return '<svg viewBox="0 0 180 110" width="165" height="100"><rect x="10" y="30" width="160" height="58" rx="12" fill="#4b5763" stroke="#aab4bd" stroke-width="3"/><rect x="28" y="16" width="124" height="20" rx="6" fill="#77838f"/><circle cx="45" cy="61" r="14" fill="#151c24"/><circle cx="135" cy="61" r="14" fill="#151c24"/><path d="M58 61h64" stroke="#d9e2e8" stroke-width="5"/></svg>';
    }
    function assemblyVisual(part,phase,ok){
      var label=phase==='pick'?'PICKING UP '+part.name.toUpperCase():phase==='install'?'INSTALLING '+part.name.toUpperCase():(ok?'ASSEMBLED · READY FOR NEXT STEP':'ASSEMBLED ANYWAY · 0 POINTS');
      var cls=phase==='pick'?'pickup':phase==='install'?'install':phase==='done'?'installed':'';
      var miss=phase==='done'&&!ok?' missed':'';
      var glow=phase==='done'&&ok?' target-glow':'';
      var targetKind=part.art==='piston'?'block':part.art;
      return '<div class="ct-assembly-visual"><div class="ct-mech-stage">'+
        '<div class="ct-part-art '+cls+miss+'" id="ct-part-art">'+svgFor(part.art)+'</div>'+
        '<div class="ct-target-art'+glow+'" id="ct-target-art">'+svgFor(targetKind)+'</div>'+
        '<div class="ct-hand-art '+cls+'" id="ct-hand-art">🖐️</div>'+
        '<div class="ct-assembly-label" id="ct-assembly-label">'+label+'</div>'+
      '</div></div>';
    }
    function animateAssembly(part,phase,ok,after){
      if(!stageEl||closed)return;
      var p=document.getElementById('ct-part-art'),h=document.getElementById('ct-hand-art'),lab=document.getElementById('ct-assembly-label');
      if(!p||!h){if(after)after();return;}
      if(phase==='pick'){
        p.classList.add('pickup');h.classList.add('pickup');if(lab)lab.textContent='PICKUP ANIMATION · '+part.name.toUpperCase();
        later(function(){if(after)after();},520);
      }else{
        p.classList.remove('pickup');p.classList.add('install');if(!ok)p.classList.add('missed');
        h.classList.remove('pickup');h.classList.add('install');
        if(lab)lab.textContent=(ok?'INSTALLATION COMPLETE':'INSTALLATION MISSED')+' · '+part.name.toUpperCase();
        later(function(){
          p.classList.remove('install');p.classList.add('installed');
          h.classList.remove('install');h.classList.add('installed');
          if(lab)lab.textContent=ok?'ASSEMBLED · +POINTS':'ASSEMBLED ANYWAY · 0 POINTS';
          if(after)after();
        },700);
      }
    }
    function timingBar(id,opts){
      opts=opts||{};var targetLeft=opts.targetLeft||40,targetWidth=opts.targetWidth||18,speed=opts.speed||1500,label=opts.label||'HIT THE GREEN';
      stageEl.insertAdjacentHTML('beforeend','<div class="ct-instruction"><b>'+label+'</b><span id="'+id+'-status">WAIT FOR THE RED MARKER TO ENTER THE GREEN.</span></div><div class="ct-timing-wrap"><div class="ct-timing-track" id="'+id+'-track"><div class="ct-green" style="left:'+targetLeft+'%;width:'+targetWidth+'%"></div><div class="ct-red" id="'+id+'-red"></div></div><button class="type-btn ct-hit" id="'+id+'-hit">HIT TIMING</button></div>');
      var red=document.getElementById(id+'-red'),hit=document.getElementById(id+'-hit'),track=document.getElementById(id+'-track'),start=performance.now(),done=false;
      function loop(now){if(done||closed)return;var p=((now-start)%speed)/speed;var x=p<=.5?p*200:(1-p)*200;red.style.left='calc('+x+'% - 7px)';raf=requestAnimationFrame(loop);}
      raf=requestAnimationFrame(loop);
      hit.onclick=function(){
        if(done||closed)return;done=true;cancelAnimationFrame(raf);raf=null;
        var rect=red.getBoundingClientRect(),green=track.querySelector('.ct-green').getBoundingClientRect(),ok=rect.left+rect.width/2>=green.left&&rect.left+rect.width/2<=green.right;
        hit.disabled=true;opts.onResult(ok);
      };
    }
    function stage1(){
      cleanup();titleEl.textContent='STAGE 1 · ENGINE ASSEMBLY';subEl.textContent='Four one-shot installations. The physical animation plays whether the timing check is correct or missed.';setProgress(0);var idx=0;score.engine=0;setScore();
      function next(){
        if(closed)return;
        if(idx>=parts.length){score.engine=Math.min(3000,score.engine);setScore();later(stage2,650);return;}
        var part=parts[idx],step=idx;setProgress(step/4*33.333);
        stageEl.innerHTML='<div class="ct-workbench"><div class="ct-workbench-side"><span>WORKBENCH</span><div class="ct-part-piece">'+(idx===0?'🔩':idx===1?'🔧':idx===2?'⚙️':'🏎️')+'<b>'+part.name+'</b><small>'+part.desc+'</small><button class="type-btn" id="ct-pick">PICK UP PART</button></div></div><div class="ct-engine-bay"><span>ENGINE BAY</span><div class="ct-engine-block">'+(idx===0?'🧱':idx===1?'⚙️':idx===2?'🔩':'🚗')+'<b>'+(['PISTON','BLOCK','CAMSHAFT','CHASSIS'][idx])+'</b><small>INSTALLATION POINT READY</small></div></div></div><div class="ct-part-step">ASSEMBLY STEP '+(idx+1)+' / 4 · 750 POINTS</div><div id="ct-install-area">'+assemblyVisual(part,'pick',false)+'</div>';
        var pick=document.getElementById('ct-pick');
        pick.onclick=function(){
          if(pick.disabled||closed)return;pick.disabled=true;
          animateAssembly(part,'pick',false,function(){
            timingBar('ct-assembly-'+step,{label:'INSTALL '+part.name.toUpperCase(),targetLeft:36+(step%2)*10,targetWidth:20,speed:1300+(step*110),onResult:function(ok){
              var st=document.getElementById('ct-assembly-'+step+'-status');if(st)st.textContent=ok?'CORRECT · +750':'MISSED · 0 POINTS · CONTINUE';
              if(ok)score.engine+=750;setScore();
              var area=document.getElementById('ct-install-area');
              if(area)area.innerHTML=assemblyVisual(part,'install',ok)+'<div id="ct-post-timing"></div>';
              animateAssembly(part,'install',ok,function(){idx++;next();});
            }});
          });
        };
      }
      next();
    }
    function shiftStage(stageName,isDownhill){
      cleanup();var count=isDownhill?10:8,idx=0,earned=0;titleEl.textContent='STAGE '+(isDownhill?'3':'2')+' · '+stageName.toUpperCase();subEl.textContent=isDownhill?'Race downhill against the AI. Shift at the timing window to keep the car ahead.':'Climb the hill without losing the engine in the wrong gear. Each correct shift is worth 375 points.';setProgress(isDownhill?66.666:33.333);
      function next(){
        if(closed)return;
        if(idx>=count){if(isDownhill)score.downhill=earned;else score.uphill=earned;setScore();later(isDownhill?finish:stage3,650);return;}
        var gear=idx%5+1;
        stageEl.innerHTML='<div class="ct-drive-hud"><div><span>SHIFT '+(idx+1)+' / '+count+'</span><b>'+gear+' → '+(gear===5?3:gear+1)+'</b></div><div class="ct-mini-ai"><span>AI</span><i style="width:'+Math.min(96,35+idx*6)+'%"></i></div></div>'+
          '<div class="ct-stage-visual"><div class="ct-road-visual"><div class="ct-road-hill">UPHILL POWERTRAIN · GEAR '+gear+'</div><div class="ct-road-car">🏎️</div><div class="ct-road-ai">🏎️</div></div><div class="ct-road-visual"><div class="ct-road-hill">'+(isDownhill?'DOWNHILL AI RACE':'HILL CLIMB')+' · SHIFT WINDOW</div><div class="ct-road-car" style="left:43%;bottom:20px">🏎️</div><div class="ct-road-ai" style="left:58%;bottom:74px">🏎️</div></div></div>';
        timingBar('ct-shift-'+(isDownhill?'down':'up')+'-'+idx,{label:'SHIFT WHEN RED ENTERS GREEN',targetLeft:42,targetWidth:16,speed:1150+((idx%3)*180),onResult:function(ok){
          var st=document.getElementById('ct-shift-'+(isDownhill?'down':'up')+'-'+idx+'-status');if(st)st.textContent=ok?'SHIFT CLEAN · +'+(isDownhill?300:375):'MISSED SHIFT · 0 POINTS';
          if(ok)earned+=isDownhill?300:375;setScore();
          later(function(){idx++;next();},360);
        }});
      }
      next();
    }
    function stage2(){shiftStage('UPHILL POWERTRAIN',false);}
    function stage3(){shiftStage('DOWNHILL AI RACE',true);}
    var originalClose=o.close;o.close=function(){closed=true;cleanup();originalClose();};
    stage1();
  }


  /* ---- 7. Drift King (car) — v2: proper drift physics ---- */
  function launchDrift(){
    var body='<div class="g519-hud"><span>Style: <b id="dk-style">0</b></span><span>Time: <b id="dk-time">30</b>s</span><span>Speed: <b id="dk-speed">0</b></span><span>Slip: <b id="dk-drift">0&deg;</b></span></div>'+
      '<canvas id="dk-canvas" width="600" height="360" class="g519-canvas"></canvas>'+
      '<p class="g519-sub" id="dk-msg" style="text-align:center;">WASD/Arrows to drive. Turn at speed to slide the rear — counter-steer to hold the drift. 30 seconds.</p>'+
      '<div class="g519-btnrow"><button class="type-btn" id="dk-start">Start</button></div>';
    var o=ovOpen('🏎️ Drift King','Drift through corners for style points.',body);
    if(!o) return;
    var cv=document.getElementById('dk-canvas'), ctx=cv.getContext('2d');
    var kt=KeyTracker(); kt.install();
    var car, score, running, startT, raf, trail, driftStreak, lastDriftFrame;

    function reset(){
      car={x:300,y:280,a:0,vx:0,vy:0}; score=0; running=false; startT=0; raf=null; trail=[]; driftStreak=0; lastDriftFrame=-100;
    }
    reset();

    function loop(){
      if(!running) return;
      var now=performance.now(); var left=Math.max(0,30-(now-startT)/1000);
      var el=document.getElementById('dk-time'); if(el) el.textContent=Math.ceil(left);

      var accel=kt.down('ArrowUp')||kt.down('w')||kt.down('W');
      var brake=kt.down('ArrowDown')||kt.down('s')||kt.down('S');
      var lkey=kt.down('ArrowLeft')||kt.down('a')||kt.down('A');
      var rkey=kt.down('ArrowRight')||kt.down('d')||kt.down('D');

      var speed=Math.sqrt(car.vx*car.vx+car.vy*car.vy);
      var velAng=Math.atan2(car.vy,car.vx);
      var slip=car.a-velAng;
      while(slip>Math.PI)slip-=2*Math.PI; while(slip<-Math.PI)slip+=2*Math.PI;
      var slipDeg=Math.abs(slip*180/Math.PI);

      // Apply acceleration in heading direction
      if(accel) { car.vx+=Math.cos(car.a)*0.18; car.vy+=Math.sin(car.a)*0.18; }
      if(brake) { car.vx*=0.94; car.vy*=0.94; }
      // Natural friction
      car.vx*=0.991; car.vy*=0.991;
      // Cap speed
      var maxSp=6;
      speed=Math.sqrt(car.vx*car.vx+car.vy*car.vy);
      if(speed>maxSp){ car.vx=(car.vx/speed)*maxSp; car.vy=(car.vy/speed)*maxSp; }

      // Steering — heading rotates, velocity follows with a lag (grip)
      var steer=(lkey?-1:0)+(rkey?1:0);
      var speedFactor=Math.min(1,speed/2.5);
      car.a+=steer*0.045*(0.4+speedFactor*0.6);

      // Grip: how strongly velocity aligns to heading. Lower = more slide.
      var grip=0.90;
      if(Math.abs(steer)>0&&speed>2){ grip=0.93-Math.min(0.10,speed*0.012); }
      // Counter-steer bonus: if steering opposite to slip, maintain drift better
      var counterSteer=(steer!==0)&&(Math.sign(steer)!==Math.sign(slip));
      if(counterSteer) grip-=0.03;

      if(speed>0.15){
        var newAng=velAng+slip*(1-grip);
        // Preserve kinetic energy — car keeps moving in roughly the same direction
        car.vx=Math.cos(newAng)*speed*grip+Math.cos(car.a)*speed*(1-grip)*0.35;
        car.vy=Math.sin(newAng)*speed*grip+Math.sin(car.a)*speed*(1-grip)*0.35;
        var ns=Math.sqrt(car.vx*car.vx+car.vy*car.vy);
        if(ns>0.01){ car.vx=(car.vx/ns)*speed*0.997; car.vy=(car.vy/ns)*speed*0.997; }
      }

      car.x+=car.vx; car.y+=car.vy;
      if(car.x<0)car.x+=cv.width; if(car.x>cv.width)car.x-=cv.width;
      if(car.y<0)car.y+=cv.height; if(car.y>cv.height)car.y-=cv.height;

      // Drift scoring: require real slip angle + adequate speed
      var drifting=slipDeg>12&&speed>2.5;
      if(drifting){
        var quality=Math.min(1,slipDeg/45);
        var speedBonus=Math.min(1,speed/6);
        driftStreak++;
        // Diminishing returns — can't farm infinite points by holding W+D
        var streakMult=Math.max(0.15,1-driftStreak*0.006);
        var pts=Math.max(1,Math.round(quality*speedBonus*3*streakMult));
        score+=pts; lastDriftFrame=now;
        trail.push({x:car.x,y:car.y,a:car.a,life:1,slip:slipDeg});
      } else {
        if(now-lastDriftFrame>400) driftStreak=0;
      }

      // Spin out if slip angle extreme
      if(slipDeg>70&&speed>3){ car.vx*=0.85; car.vy*=0.85; }

      var se=document.getElementById('dk-style'); if(se) se.textContent=score;
      var sp=document.getElementById('dk-speed'); if(sp) sp.textContent=Math.round(speed*12);
      var dr=document.getElementById('dk-drift'); if(dr) dr.textContent=Math.round(slipDeg)+'\u00b0';

      for(var i=trail.length-1;i>=0;i--){ trail[i].life-=0.022; if(trail[i].life<=0)trail.splice(i,1); }

      // Draw
      ctx.fillStyle='#0a0e16'; ctx.fillRect(0,0,cv.width,cv.height);
      ctx.strokeStyle='rgba(255,255,255,.07)'; ctx.lineWidth=52;
      ctx.beginPath(); ctx.ellipse(300,180,200,110,0,0,Math.PI*2); ctx.stroke();
      ctx.strokeStyle='rgba(255,255,255,.04)'; ctx.lineWidth=46;
      ctx.beginPath(); ctx.ellipse(300,180,150,75,0,0,Math.PI*2); ctx.stroke();

      trail.forEach(function(tr){
        ctx.save(); ctx.translate(tr.x,tr.y); ctx.rotate(tr.a);
        var a=tr.life*0.5;
        ctx.fillStyle='rgba(35,35,40,'+a+')'; ctx.fillRect(-11,-8,22,3); ctx.fillRect(-11,5,22,3);
        if(tr.slip>20){ ctx.fillStyle='rgba(224,164,88,'+(a*0.4)+')'; ctx.fillRect(-11,-8,22,16); }
        ctx.restore();
      });

      ctx.save(); ctx.translate(car.x,car.y); ctx.rotate(car.a);
      ctx.fillStyle='#e0a458'; ctx.fillRect(-13,-7,26,14);
      ctx.fillStyle='#0b0e16'; ctx.fillRect(-2,-5,8,10);
      ctx.fillStyle='#ffd54a'; ctx.fillRect(10,-5,3,3); ctx.fillRect(10,2,3,3);
      ctx.restore();

      if(drifting){ ctx.fillStyle='rgba(224,164,88,.85)'; ctx.font='bold 13px Inter,sans-serif'; ctx.textAlign='center'; ctx.fillText('DRIFTING',car.x,car.y-22); }

      if(left<=0){ running=false; stop(); return; }
      raf=requestAnimationFrame(loop);
    }
    function stop(){ if(raf)cancelAnimationFrame(raf); kt.dispose(); var m=document.getElementById('dk-msg'); if(m)m.textContent='Time! '+score+' style points.'; endGame('drift519','drift',score); }
    document.getElementById('dk-start').addEventListener('click', function(){ kt.install();
      reset(); running=true; startT=performance.now();
      var s=document.getElementById('dk-style'); if(s)s.textContent='0';
      var m=document.getElementById('dk-msg'); if(m)m.textContent='Drift!';
      if(raf)cancelAnimationFrame(raf); raf=requestAnimationFrame(loop);
    });
    ctx.fillStyle='#0a0e16'; ctx.fillRect(0,0,cv.width,cv.height);
    ctx.strokeStyle='rgba(255,255,255,.07)'; ctx.lineWidth=52;
    ctx.beginPath(); ctx.ellipse(300,180,200,110,0,0,Math.PI*2); ctx.stroke();
    var origClose=o.close; o.close=function(){ if(raf)cancelAnimationFrame(raf); kt.dispose(); origClose(); };
  }



