    var o=ovOpen('🏎️ F1 Cockpit','First-person race simulator with sequential shifting, live engineering telemetry, tire/brake data, track conditions, AI rivals, and a functional live map.',body); if(!o) return; o.shell.classList.add('f1-modal');
