     /* ---- 5.52.0 tyres, pit stops, corner coach ---- */
     var F1_COMP={soft:{k:.42,acc:1,n:'SOFT',c:'#ff4d4d'},medium:{k:.26,acc:.94,n:'MEDIUM',c:'#ffd84d'},hard:{k:.16,acc:.88,n:'HARD',c:'#ffffff'}},F1_COMP_LIST=['soft','medium','hard'];
     var f1Sel='medium',f1Comp='medium',f1Wear=0,f1PitReq=false,f1PitUntil=0,f1CoachRows=[],f1PL=false,f1TL=false;
     function f1TyreGrip(){ return F1_COMP[f1Comp].acc*(1-.5*f1Wear*f1Wear); }
